#!/usr/bin/env python
# -*- coding: utf-8 -*-
import base64, pathlib, shutil
BASE = pathlib.Path(__file__).parent
files = {'newmoon_app/config/urls.py': '', 'newmoon_app/store/urls.py': '', 'newmoon_app/store/manager_views.py': '', 'newmoon_app/store/forms.py': '', 'newmoon_app/store/utils.py': '', 'newmoon_app/store/decorators.py': '', 'newmoon_app/templates/manager/dashboard.html': '', 'newmoon_app/templates/manager/product_list.html': '', 'newmoon_app/templates/manager/product_form.html': '', 'newmoon_app/templates/manager/bulk_price.html': ''}
for rel,b64 in files.items():
    p = BASE / rel.split('/',1)[1] if rel.startswith('newmoon_app/') else BASE / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
    print('✓', p)
for d in [BASE/'store'/'__pycache__', BASE/'config'/'__pycache__']:
    if d.exists(): shutil.rmtree(d); print('x cleared', d)
print('\n✅ Panel v7 installed - now run START.py')
